    /// <summary>
    /// CoC
    /// </summary>
    /// <param name = "_fieldId">_fieldId</param>
    public void modifiedField(FieldId _fieldId)
    {
        next modifiedField(_fieldId);

        switch(_fieldId)
        {            
            // MPJ_21310_SalesItemSubstitutes
            case fieldNum(CustParameters, METSalesSubstituteMaxLevels):
                this.METSalesSubstituteMaxLevels = real2int(abs(min(
                    METSalesItemSubstitution::maxSearchDepth(),
                    this.METSalesSubstituteMaxLevels)));
                break;
        }
    }
